// Expanded Vietnamese history data — timeline, 4-month roadmap with 10 lessons each
import type { HistoryEvent, HistoryMonth } from "./types";

export const historyTimeline: HistoryEvent[] = [
  { year: "2879 TCN", title: "Hùng Vương lập nước", titleEn: "Hung Kings Founded Nation", icon: "👑", description: "Vua Hùng lập nước Văn Lang – nhà nước đầu tiên của người Việt, kéo dài 18 đời vua, kinh đô đặt tại Phong Châu (Phú Thọ ngày nay). Lãnh thổ trải dài từ miền nam Trung Quốc đến vùng Bắc Trung Bộ, với nền kinh tế nông nghiệp lúa nước phát triển. Truyền thuyết Lạc Long Quân và Âu Cơ kể rằng người Việt sinh ra từ bọc trăm trứng – thể hiện tinh thần đoàn kết 'đồng bào' (cùng một bào thai). Ngày Giỗ Tổ Hùng Vương (10/3 Âm lịch) được công nhận là Quốc lễ và Di sản Văn hóa Phi vật thể của UNESCO.", descriptionEn: "King Hung founded Van Lang – Vietnam's first state, lasting 18 generations with the capital at Phong Chau (modern Phu Tho). The territory stretched from southern China to north-central Vietnam, with a thriving wet-rice agricultural economy. The legend of Lac Long Quan and Au Co tells that Vietnamese were born from a sack of 100 eggs – embodying the spirit of 'dong bao' (compatriots, literally 'from the same womb'). Hung Kings' Commemoration Day (March 10 lunar calendar) is a national holiday and UNESCO Intangible Cultural Heritage." },
  { year: "~2000 TCN", title: "Văn hóa Phùng Nguyên", titleEn: "Phung Nguyen Culture", icon: "🏺", description: "Thời kỳ đồ đồng sớm ở lưu vực sông Hồng, với các hiện vật gốm và công cụ đá tinh xảo. Các di chỉ khảo cổ tại Phú Thọ, Vĩnh Phúc cho thấy cư dân đã biết trồng lúa, nuôi gia súc và chế tác đồ trang sức bằng ngọc. Kỹ thuật đúc đồng bắt đầu phát triển, đặt nền móng cho nền văn hóa Đông Sơn rực rỡ sau này. Đây là giai đoạn chuyển tiếp quan trọng từ thời đồ đá sang thời đại kim khí tại Đông Nam Á.", descriptionEn: "Early Bronze Age culture in the Red River basin, featuring refined pottery and stone tools. Archaeological sites in Phu Tho and Vinh Phuc reveal that inhabitants practiced rice cultivation, raised livestock, and crafted jade jewelry. Bronze casting techniques began developing, laying the groundwork for the later brilliant Dong Son culture. This was a critical transition period from the Stone Age to the Metal Age in Southeast Asia." },
  { year: "~700 TCN", title: "Văn hóa Đông Sơn", titleEn: "Dong Son Culture", icon: "🥁", description: "Nền văn hóa nổi tiếng với trống đồng Đông Sơn – biểu tượng văn hóa Việt Nam. Kỹ thuật đúc đồng đạt đỉnh cao, thể hiện qua hoa văn tinh xảo về đời sống, lễ hội và chiến trận. Trống đồng Ngọc Lũ là hiện vật tiêu biểu nhất, với hoa văn chim Lạc, thuyền chiến và cảnh lễ hội. Các sản phẩm đồng Đông Sơn được tìm thấy khắp Đông Nam Á, chứng tỏ mạng lưới giao thương rộng lớn. Người Đông Sơn sống trong nhà sàn, thạo nghề đi biển và có tổ chức xã hội phức tạp.", descriptionEn: "Famous for the Dong Son bronze drums – iconic Vietnamese cultural symbols. Bronze casting reached its peak, with intricate patterns depicting daily life, festivals, and battles. The Ngoc Lu drum is the most representative artifact, featuring patterns of Lac birds, war boats, and festival scenes. Dong Son bronze products found across Southeast Asia prove an extensive trade network. Dong Son people lived in stilt houses, were skilled seafarers, and had complex social organization." },
  { year: "257 TCN", title: "An Dương Vương lập Âu Lạc", titleEn: "Au Lac Founded", icon: "🏰", description: "Thục Phán (An Dương Vương) thống nhất Văn Lang và Âu Việt, lập nước Âu Lạc. Xây thành Cổ Loa hình xoáy ốc – công trình quân sự độc đáo gồm 9 vòng thành lồng nhau, kinh đô đầu tiên của Âu Lạc (nay thuộc Đông Anh, Hà Nội). Truyền thuyết kể rằng thần Kim Quy giúp xây thành và tặng nỏ thần bắn một phát giết hàng ngàn quân địch. Câu chuyện tình bi thương giữa Mỵ Châu (con gái An Dương Vương) và Trọng Thủy (con trai Triệu Đà) là bài học sâu sắc về cảnh giác quốc phòng.", descriptionEn: "Thuc Phan (An Duong Vuong) unified Van Lang and Au Viet, founding Au Lac. Built the spiral-shaped Co Loa citadel – a unique military structure with 9 concentric walls, Au Lac's first capital (now in Dong Anh, Hanoi). Legend tells that the Golden Turtle God helped build the fortress and gifted a magic crossbow that could kill thousands with one shot. The tragic love story between My Chau (An Duong Vuong's daughter) and Trong Thuy (Trieu Da's son) is a profound lesson about national defense vigilance." },
  { year: "207 TCN", title: "Triệu Đà lập Nam Việt", titleEn: "Trieu Da Founded Nam Viet", icon: "🗺️", description: "Triệu Đà lập nước Nam Việt sau khi sáp nhập Âu Lạc, kinh đô tại Phiên Ngung (Quảng Châu ngày nay). Lãnh thổ trải dài từ nam Trung Quốc đến miền Bắc Việt Nam. Triệu Đà áp dụng chính sách 'hòa tập bách Việt', tôn trọng phong tục địa phương, mặc áo cài trái theo kiểu Việt và tự xưng 'Nam Việt Vũ Đế'. Giai đoạn này chứng kiến sự giao thoa sâu sắc giữa văn hóa Hoa và Việt, nhiều kỹ thuật nông nghiệp và thủ công mỹ nghệ được truyền bá.", descriptionEn: "Trieu Da founded Nam Viet after annexing Au Lac, with capital at Panyu (modern Guangzhou). Territory stretched from southern China to northern Vietnam. Trieu Da adopted 'harmony with Hundred Viet' policy, respecting local customs, wearing left-fastened robes in Vietnamese style, and proclaimed himself 'Emperor Wu of Nam Viet'. This period witnessed deep Sino-Vietnamese cultural exchange, with many agricultural and artisanal techniques being disseminated." },
  { year: "111 TCN", title: "Bắc thuộc lần 1", titleEn: "First Chinese Domination", icon: "⛓️", description: "Nhà Hán chiếm Âu Lạc, biến thành quận Giao Chỉ. Bắt đầu hơn 1000 năm Bắc thuộc nhưng người Việt vẫn giữ vững bản sắc văn hóa, ngôn ngữ riêng. Chính quyền Hán áp đặt thuế nặng, cống nạp sản vật quý (ngọc trai, sừng tê, ngà voi) và đồng hóa văn hóa. Tuy nhiên, người Việt tiếp thu có chọn lọc: chữ Hán, kỹ thuật luyện sắt và thủy lợi được áp dụng, đồng thời vẫn bảo tồn tiếng Việt, tục nhuộm răng đen, xăm mình và tín ngưỡng thờ Mẫu.", descriptionEn: "Han Dynasty conquered Au Lac, turning it into Giao Chi province. Began over 1000 years of Chinese rule, yet Vietnamese preserved their cultural identity and language. The Han imposed heavy taxes, demanded tribute of precious goods (pearls, rhino horns, ivory), and cultural assimilation. However, Vietnamese selectively adopted Chinese script, iron-smelting and irrigation techniques while preserving the Vietnamese language, customs of teeth blackening, tattooing, and Mother Goddess worship." },
  { year: "40", title: "Khởi nghĩa Hai Bà Trưng", titleEn: "Trung Sisters' Uprising", description: "Trưng Trắc và Trưng Nhị khởi nghĩa chống quân Hán, giải phóng 65 thành trì từ Cửu Chân đến Hợp Phố. Cuộc khởi nghĩa đầu tiên do phụ nữ lãnh đạo trong lịch sử Việt Nam, lập ra nhà nước độc lập ngắn ngủi 3 năm (40-43). Trưng Trắc xưng vương, đóng đô ở Mê Linh. Đặc biệt, trong số 63 tướng lĩnh có đến hơn 30 người là nữ, bao gồm các nữ tướng nổi tiếng như Phật Nguyệt, Lê Chân, Thánh Thiên. Hai Bà Trưng được tôn thờ tại hàng trăm đền thờ khắp Việt Nam.", descriptionEn: "Trung Trac and Trung Nhi led an uprising against Han rule, liberating 65 citadels from Cuu Chan to Hop Pho. Vietnam's first female-led revolt, establishing a brief 3-year independent state (40-43). Trung Trac proclaimed herself queen, with capital at Me Linh. Remarkably, among 63 generals, over 30 were women, including famous female commanders like Phat Nguyet, Le Chan, and Thanh Thien. The Trung Sisters are worshipped at hundreds of temples across Vietnam." },
  { year: "248", title: "Khởi nghĩa Bà Triệu", titleEn: "Lady Trieu's Uprising", description: "Triệu Thị Trinh (Bà Triệu) 19 tuổi lãnh đạo nghĩa quân chống nhà Ngô. Nổi tiếng với tuyên ngôn: 'Tôi muốn cưỡi cơn gió mạnh, đạp luồng sóng dữ, chém cá kình ở biển Đông, quét sạch bờ cõi để cứu dân ra khỏi nơi đắm đuối, chứ không chịu khom lưng làm tì thiếp người ta.' Bà mồ côi cha mẹ từ nhỏ, nuôi chí lớn, tập hợp hàng ngàn nghĩa quân trên núi Nưa (Thanh Hóa). Dù thất bại, tinh thần bất khuất của Bà Triệu đã truyền cảm hứng cho nhiều thế hệ người Việt.", descriptionEn: "Trieu Thi Trinh (Lady Trieu), at age 19, led an army against the Wu Dynasty. Famous for declaring: 'I want to ride the storm, tread dangerous waves, slay the sharks of the Eastern Sea, sweep the entire territory to save people from drowning, rather than bow down as a concubine.' Orphaned as a child, she nurtured great ambitions and gathered thousands of warriors on Nua Mountain (Thanh Hoa). Despite defeat, Lady Trieu's indomitable spirit has inspired generations of Vietnamese." },
  { year: "544", title: "Lý Nam Đế lập Vạn Xuân", titleEn: "Ly Nam De Founded Van Xuan", description: "Lý Bí đánh đuổi quân Lương, tự xưng Lý Nam Đế, lập nước Vạn Xuân (nghĩa là 'muôn mùa xuân') – thể hiện khát vọng độc lập trường tồn của dân tộc. Ông xây Long Biên thành (Hà Nội ngày nay) làm kinh đô, thiết lập hệ thống hành chính và quân sự riêng. Nước Vạn Xuân tồn tại khoảng 60 năm. Sau khi Lý Nam Đế mất, tướng Triệu Quang Phục tiếp tục kháng chiến tại đầm Dạ Trạch với chiến thuật du kích nổi tiếng 'ban ngày ẩn, ban đêm đánh'.", descriptionEn: "Ly Bi expelled the Liang forces, proclaimed himself Ly Nam De, and founded Van Xuan ('Ten Thousand Springs') – expressing the nation's aspiration for eternal independence. He built Long Bien citadel (modern Hanoi) as capital and established independent administrative and military systems. Van Xuan lasted about 60 years. After Ly Nam De's death, General Trieu Quang Phuc continued resistance at Da Trach swamp with the famous guerrilla tactic 'hide by day, strike by night'." },
  { year: "938", title: "Ngô Quyền thắng Bạch Đằng", titleEn: "Ngo Quyen's Bach Dang Victory", description: "Ngô Quyền cắm cọc nhọn bọc sắt dưới sông Bạch Đằng, lợi dụng thủy triều lên dụ thuyền chiến Nam Hán vào bẫy. Khi thủy triều rút, thuyền giặc bị cọc đâm thủng, quân Việt đổ ra đánh, tướng Nam Hán Lưu Hoằng Tháo tử trận. Chiến thắng lừng lẫy chấm dứt hơn 1000 năm Bắc thuộc, mở ra kỷ nguyên độc lập lâu dài. Ngô Quyền xưng vương, đóng đô ở Cổ Loa, đặt quan chế, chính triều nghi – khẳng định nền tự chủ hoàn toàn.", descriptionEn: "Ngo Quyen planted iron-tipped stakes in the Bach Dang River, using the tides to trap Southern Han warships. When the tide receded, enemy ships were impaled on stakes, and Vietnamese forces attacked; Southern Han commander Liu Hongcao was killed. This legendary victory ended over 1000 years of Chinese rule, opening an era of lasting independence. Ngo Quyen proclaimed himself king, established court at Co Loa, set up bureaucracy and court rituals – affirming complete sovereignty." },
  { year: "968", title: "Đinh Bộ Lĩnh thống nhất", titleEn: "Dinh Bo Linh Unified", description: "Đinh Bộ Lĩnh dẹp loạn 12 sứ quân, thống nhất đất nước, lập nhà Đinh. Đặt quốc hiệu Đại Cồ Việt, kinh đô tại Hoa Lư (Ninh Bình) – cố đô lịch sử nổi tiếng được UNESCO công nhận. Từ nhỏ, Đinh Bộ Lĩnh đã nổi tiếng với trò chơi 'cờ lau tập trận' cùng trẻ chăn trâu, thể hiện tài lãnh đạo bẩm sinh. Ông thiết lập hệ thống quân sự 10 đạo, bang giao với nhà Tống, giữ vững hòa bình và chủ quyền quốc gia.", descriptionEn: "Dinh Bo Linh pacified the 12 warlords, unified the country, and founded the Dinh Dynasty. Named the nation Dai Co Viet with capital at Hoa Lu (Ninh Binh) – a famous historical capital recognized by UNESCO. As a child, Dinh Bo Linh was famous for the game 'reed-flag war exercises' with buffalo-herding boys, showing innate leadership. He established a 10-circuit military system, maintained diplomacy with the Song Dynasty, and preserved peace and national sovereignty." },
  { year: "1010", title: "Lý Thái Tổ dời đô Thăng Long", titleEn: "Capital Moved to Thang Long", description: "Lý Thái Tổ ban 'Chiếu dời đô', chuyển kinh đô từ Hoa Lư đến Thăng Long (Hà Nội ngày nay). Truyền thuyết kể vua thấy rồng vàng bay lên nên đặt tên Thăng Long – 'Rồng bay lên'. Chiếu dời đô phân tích vị trí địa lý trung tâm, thuận lợi giao thông và phong thủy tốt lành. Thăng Long nhanh chóng trở thành trung tâm chính trị, kinh tế, văn hóa của cả nước với 36 phố phường sầm uất. Quyết định này đánh dấu tầm nhìn chiến lược vượt thời đại của Lý Thái Tổ.", descriptionEn: "Ly Thai To issued the 'Edict on Moving the Capital' from Hoa Lu to Thang Long (modern Hanoi). Legend says the king saw a golden dragon ascending, naming it Thang Long – 'Rising Dragon'. The edict analyzed the central geographic location, convenient transportation, and auspicious feng shui. Thang Long quickly became the political, economic, and cultural center with its bustling 36 streets and guilds. This decision marked Ly Thai To's visionary strategic thinking ahead of his time." },
  { year: "1070", title: "Xây Văn Miếu", titleEn: "Temple of Literature Built", description: "Lý Thánh Tông xây Văn Miếu thờ Khổng Tử. Năm 1076, lập Quốc Tử Giám – trường đại học đầu tiên của Việt Nam, đào tạo nhân tài cho đất nước qua nhiều thế kỷ. 82 bia Tiến sĩ ghi danh 1307 vị đỗ đạt từ năm 1442 đến 1779 được UNESCO công nhận là Di sản Tư liệu Thế giới. Văn Miếu – Quốc Tử Giám thể hiện truyền thống hiếu học của người Việt: 'Hiền tài là nguyên khí quốc gia', là biểu tượng văn hóa giáo dục hàng đầu Việt Nam đến ngày nay.", descriptionEn: "Ly Thanh Tong built the Temple of Literature dedicated to Confucius. In 1076, founded Quoc Tu Giam – Vietnam's first university, training talents for the nation across centuries. 82 Doctor's Stelae recording 1,307 graduates from 1442 to 1779 are recognized as UNESCO Memory of the World. The Temple of Literature symbolizes Vietnamese scholarly tradition: 'Talented and virtuous people are the vital force of the nation', remaining Vietnam's premier cultural-educational symbol today." },
  { year: "1075", title: "Lý Thường Kiệt đánh Tống", titleEn: "Ly Thuong Kiet vs Song", description: "Lý Thường Kiệt chủ động tấn công phủ đầu quân Tống, tiến đánh 3 châu Ung, Khâm, Liêm (nam Trung Quốc). Sau đó rút về xây phòng tuyến sông Như Nguyệt và viết bài thơ bất hủ 'Nam quốc sơn hà Nam đế cư' – bản tuyên ngôn độc lập đầu tiên của Việt Nam. Bài thơ được vang lên trong đêm khiến quân Tống hoảng sợ, tin rằng thần linh phù hộ người Việt. Chiến lược 'tiên phát chế nhân' (tấn công trước để kiểm soát đối phương) của ông là bài học quân sự kinh điển.", descriptionEn: "Ly Thuong Kiet launched a preemptive strike against the Song Dynasty, attacking three prefectures of Yong, Qin, and Lian (southern China). He then retreated to build the Nhu Nguyet River defense line and composed the immortal poem 'Southern Mountains and Rivers' – Vietnam's first declaration of independence. The poem echoed at night, terrifying Song troops who believed divine spirits protected the Vietnamese. His 'strike first to control the enemy' strategy remains a classic military lesson." },
  { year: "1258", title: "Kháng Nguyên Mông lần 1", titleEn: "First Mongol Defense", description: "Nhà Trần đánh bại đế quốc Mông Cổ hùng mạnh nhất thế giới lần thứ nhất. Vua Trần Thái Tông trực tiếp chỉ huy, áp dụng chiến thuật 'vườn không nhà trống' – tiêu thổ kháng chiến. Trước đó, tại Hội nghị Diên Hồng, các bô lão đồng thanh hô 'Đánh!', thể hiện ý chí toàn dân. Quân dân nhà Trần 3 lần đánh bại Mông Cổ (1258, 1285, 1288) – đế quốc từng chinh phục từ Á sang Âu. Tinh thần 'Sát Thát' (giết giặc Mông) được xăm lên tay mỗi binh sĩ.", descriptionEn: "The Tran Dynasty defeated the world's most powerful Mongol Empire for the first time. King Tran Thai Tong personally commanded, using scorched-earth tactics. Before the battle, at the Dien Hong Conference, elders unanimously shouted 'Fight!', expressing the will of all people. The Tran military and people defeated the Mongols three times (1258, 1285, 1288) – an empire that had conquered from Asia to Europe. The spirit of 'Sat That' (Kill the Mongols) was tattooed on every soldier's arm." },
  { year: "1288", title: "Trận Bạch Đằng 1288", titleEn: "Bach Dang 1288", description: "Hưng Đạo Vương Trần Quốc Tuấn tái sử dụng chiến thuật cọc nhọn trên sông Bạch Đằng, đánh tan quân Nguyên Mông lần thứ 3. Ông viết 'Hịch tướng sĩ' – bài hịch bất hủ khích lệ tinh thần chiến đấu: 'Ta thường tới bữa quên ăn, nửa đêm vỗ gối, ruột đau như cắt, nước mắt đầm đìa.' Trần Quốc Tuấn được tôn vinh là anh hùng dân tộc vĩ đại nhất, được phong 'Đức Thánh Trần' và thờ phụng khắp cả nước. Cuốn binh thư 'Vạn Kiếp tông bí truyền thư' của ông là di sản quân sự quý báu.", descriptionEn: "Tran Quoc Tuan (Hung Dao Vuong) reused the iron-stake tactic on Bach Dang River, defeating the Mongols for the third time. He wrote the 'Proclamation to Officers' – an immortal rallying cry: 'I often forget meals, pat my pillow at midnight, my heart aches as if being cut, tears streaming down.' He is revered as Vietnam's greatest national hero, honored as 'Holy Tran' and worshipped nationwide. His military treatise 'Van Kiep Master's Secret Book' is a precious military heritage." },
  { year: "1428", title: "Lê Lợi đuổi quân Minh", titleEn: "Le Loi Expelled Ming", description: "Sau 10 năm kháng chiến gian khổ (1418-1428), Lê Lợi đánh đuổi quân Minh, lập nhà Hậu Lê. Nguyễn Trãi soạn 'Bình Ngô đại cáo' – áng văn bất hủ tuyên bố độc lập, được coi là bản Tuyên ngôn Độc lập thứ hai. Mở đầu bằng câu: 'Như nước Đại Việt ta từ trước, vốn xưng nền văn hiến đã lâu.' Truyền thuyết Hồ Gươm kể rằng thần rùa Kim Quy cho Lê Lợi mượn gươm thần để đánh giặc, sau khi thắng trận đòi lại gươm tại hồ Hoàn Kiếm.", descriptionEn: "After 10 years of arduous resistance (1418-1428), Le Loi expelled the Ming forces and founded the Later Le Dynasty. Nguyen Trai composed the 'Great Proclamation upon the Pacification of Wu' – an immortal declaration of independence, considered Vietnam's second Declaration of Independence. It opens: 'Our Dai Viet nation has long been a land of ancient civilization.' The Ho Guom legend tells that the Golden Turtle God lent Le Loi a divine sword to fight invaders, then reclaimed it at Hoan Kiem Lake." },
  { year: "1471", title: "Bộ luật Hồng Đức", titleEn: "Hong Duc Legal Code", description: "Lê Thánh Tông ban hành Bộ luật Hồng Đức – bộ luật tiến bộ nhất Đông Nam Á lúc bấy giờ, gồm 722 điều luật. Đặc biệt bảo vệ quyền lợi phụ nữ: con gái được thừa kế tài sản ngang bằng con trai, vợ có quyền ly hôn chồng. Bộ luật cũng bảo vệ người yếu thế, quy định cứu tế người nghèo, trừng phạt tham nhũng nặng. Dưới thời Lê Thánh Tông, Đại Việt trở thành cường quốc khu vực với hệ thống giáo dục, thi cử và hành chính tiên tiến.", descriptionEn: "Le Thanh Tong issued the Hong Duc Legal Code – Southeast Asia's most progressive legal code at the time, comprising 722 articles. Notably protecting women's rights: daughters could inherit property equally with sons, wives could divorce husbands. The code also protected vulnerable groups, mandated poverty relief, and severely punished corruption. Under Le Thanh Tong, Dai Viet became a regional power with advanced education, examination, and administrative systems." },
  { year: "1789", title: "Quang Trung đại phá quân Thanh", titleEn: "Quang Trung vs Qing", description: "Hoàng đế Quang Trung (Nguyễn Huệ) hành quân thần tốc từ Phú Xuân ra Thăng Long, chỉ trong 5 ngày Tết Kỷ Dậu đánh tan 29 vạn quân Thanh – một trong những chiến thắng vĩ đại nhất lịch sử quân sự thế giới. Quân Tây Sơn vừa đi vừa ăn Tết, đến nơi đánh ngay không cho giặc kịp trở tay. Trận Ngọc Hồi – Đống Đa ngày mùng 5 Tết là đòn quyết định. Tướng giặc Sầm Nghi Đống thắt cổ tự tử. Quang Trung còn nổi tiếng với cải cách chữ Nôm, khuyến nông và ngoại giao khéo léo.", descriptionEn: "Emperor Quang Trung (Nguyen Hue) marched at lightning speed from Phu Xuan to Thang Long, defeating 290,000 Qing troops in just 5 days during Tet – one of the greatest military victories in world history. Tay Son troops celebrated Tet while marching, arriving and attacking immediately. The Ngoc Hoi – Dong Da battle on the 5th day of Tet was the decisive blow. Qing commander Sam Nghi Dong hanged himself. Quang Trung was also famous for Nom script reform, agriculture promotion, and skillful diplomacy." },
  { year: "1802", title: "Gia Long thống nhất", titleEn: "Gia Long Unified Vietnam", description: "Nguyễn Ánh lên ngôi Hoàng đế Gia Long, thống nhất đất nước sau hơn 200 năm chia cắt Đàng Trong – Đàng Ngoài. Đặt quốc hiệu Việt Nam, kinh đô tại Huế. Xây dựng Kinh thành Huế theo kiến trúc Vauban (Pháp) kết hợp phong thủy phương Đông, ngày nay là Di sản Thế giới UNESCO. Nhà Nguyễn mở rộng lãnh thổ về phía Nam, thiết lập chủ quyền tại Hoàng Sa và Trường Sa. Triều đình tổ chức hệ thống hành chính 31 tỉnh, kế thừa và phát triển hệ thống thi cử Nho học.", descriptionEn: "Nguyen Anh became Emperor Gia Long, unifying the country after over 200 years of North-South division. Named the nation Vietnam with capital in Hue. Built the Hue Imperial Citadel combining Vauban (French) architecture with Eastern feng shui, now a UNESCO World Heritage Site. The Nguyen Dynasty expanded territory southward and established sovereignty over Hoang Sa and Truong Sa islands. The court organized 31 provinces and continued the Confucian examination system." },
  { year: "1858", title: "Pháp xâm lược", titleEn: "French Invasion", description: "Liên quân Pháp-Tây Ban Nha tấn công cảng Đà Nẵng, mở đầu cuộc xâm lược kéo dài gần 100 năm. Pháp lần lượt chiếm Nam Kỳ (1862), Bắc Kỳ (1883) và áp đặt chế độ bảo hộ. Nhiều phong trào kháng Pháp nổi lên: Cần Vương (Tôn Thất Thuyết), Đông Du (Phan Bội Châu), Duy Tân (Phan Chu Trinh), Yên Bái (Nguyễn Thái Học). Dù thất bại, các phong trào này thể hiện tinh thần bất khuất và đặt nền tảng cho phong trào giải phóng dân tộc thế kỷ 20.", descriptionEn: "Franco-Spanish forces attacked Da Nang port, beginning nearly 100 years of colonial rule. France successively occupied Cochinchina (1862), Tonkin (1883), and imposed a protectorate. Many anti-French movements arose: Can Vuong (Ton That Thuyet), Dong Du (Phan Boi Chau), Duy Tan (Phan Chu Trinh), Yen Bai (Nguyen Thai Hoc). Despite failure, these movements embodied the indomitable spirit and laid the foundation for the 20th-century national liberation movement." },
  { year: "1930", title: "Đảng Cộng sản VN", titleEn: "Communist Party Founded", description: "Nguyễn Ái Quốc (Hồ Chí Minh) thống nhất các tổ chức cộng sản, thành lập Đảng Cộng sản Việt Nam tại Hương Cảng (Hong Kong) ngày 3/2/1930. Trước đó, Nguyễn Ái Quốc đã bôn ba 30 năm qua Pháp, Anh, Mỹ, Liên Xô để tìm đường cứu nước. Cùng năm, phong trào Xô Viết Nghệ Tĩnh bùng nổ – lần đầu tiên nông dân Việt Nam lập chính quyền Xô Viết. Sự kiện này đánh dấu bước ngoặt quyết định trong phong trào giải phóng dân tộc.", descriptionEn: "Nguyen Ai Quoc (Ho Chi Minh) unified communist organizations, founding the Communist Party of Vietnam in Hong Kong on February 3, 1930. Before this, Nguyen Ai Quoc had traveled for 30 years through France, England, America, and the Soviet Union seeking a path to national salvation. That same year, the Nghe Tinh Soviet movement erupted – the first time Vietnamese peasants established Soviet-style governance. This marked a decisive turning point in the national liberation movement." },
  { year: "1945", title: "Tuyên ngôn Độc lập", titleEn: "Independence Declaration", description: "Ngày 2/9/1945, Chủ tịch Hồ Chí Minh đọc Tuyên ngôn Độc lập tại Quảng trường Ba Đình, Hà Nội, khai sinh nước Việt Nam Dân chủ Cộng hòa trước hàng trăm ngàn đồng bào. Mở đầu bằng câu trích từ Tuyên ngôn Độc lập Hoa Kỳ: 'Tất cả mọi người đều sinh ra có quyền bình đẳng.' Trước đó, Cách mạng Tháng Tám đã giành chính quyền trên cả nước chỉ trong 2 tuần, Hoàng đế Bảo Đại thoái vị ngày 25/8, trao ấn kiếm cho chính phủ lâm thời.", descriptionEn: "On September 2, 1945, President Ho Chi Minh read the Declaration of Independence at Ba Dinh Square, Hanoi, establishing the Democratic Republic of Vietnam before hundreds of thousands of compatriots. It opened with a quote from the US Declaration of Independence: 'All men are created equal.' Prior to this, the August Revolution seized power nationwide in just 2 weeks; Emperor Bao Dai abdicated on August 25, handing the royal seal and sword to the provisional government." },
  { year: "1954", title: "Chiến thắng Điện Biên Phủ", titleEn: "Dien Bien Phu Victory", description: "Sau 56 ngày đêm chiến đấu ác liệt (13/3 - 7/5/1954), quân đội Việt Nam dưới sự chỉ huy của Đại tướng Võ Nguyên Giáp đánh bại Pháp tại Điện Biên Phủ – 'lừng lẫy năm châu, chấn động địa cầu'. Hơn 260.000 dân công tham gia vận chuyển lương thực, vũ khí qua núi rừng hiểm trở bằng xe đạp thồ. Pháo binh Việt Nam kéo pháo vào núi rồi bắn trực tiếp xuống lòng chảo – chiến thuật chưa từng có. Tướng Pháp De Castries cùng toàn bộ tham mưu bị bắt sống. Chiến thắng này dẫn đến Hiệp định Genève, chấm dứt chiến tranh Đông Dương.", descriptionEn: "After 56 days and nights of fierce battle (March 13 - May 7, 1954), Vietnamese forces under General Vo Nguyen Giap defeated France at Dien Bien Phu – a victory that 'shook the world'. Over 260,000 civilians transported supplies through treacherous mountains using reinforced bicycles. Vietnamese artillery was hauled into mountains to fire directly into the valley basin – an unprecedented tactic. French General De Castries and his entire staff were captured alive. This victory led to the Geneva Accords, ending the First Indochina War." },
  { year: "1975", title: "Thống nhất đất nước", titleEn: "National Reunification", description: "Ngày 30/4/1975, xe tăng quân giải phóng húc đổ cổng Dinh Độc Lập, Sài Gòn. Kết thúc 30 năm chiến tranh, thống nhất đất nước sau 21 năm chia cắt tại vĩ tuyến 17. Chiến dịch Hồ Chí Minh bắt đầu từ 26/4 với 5 mũi tấn công đồng loạt. Tổng thống Dương Văn Minh tuyên bố đầu hàng vô điều kiện lúc 11:30. Sài Gòn được đổi tên thành Thành phố Hồ Chí Minh. Hàng triệu gia đình ly tán được đoàn tụ. Đất nước bước vào kỷ nguyên hòa bình, thống nhất và xây dựng.", descriptionEn: "On April 30, 1975, liberation army tanks crashed through the gates of Independence Palace, Saigon. Ending 30 years of war, reunifying the country after 21 years of division at the 17th parallel. The Ho Chi Minh Campaign began April 26 with 5 simultaneous attack columns. President Duong Van Minh declared unconditional surrender at 11:30 AM. Saigon was renamed Ho Chi Minh City. Millions of separated families were reunited. The nation entered an era of peace, unity, and reconstruction." },
  { year: "1986", title: "Đổi Mới", titleEn: "Doi Moi Reform", description: "Đại hội Đảng lần thứ VI khởi xướng chính sách Đổi Mới – chuyển từ kinh tế kế hoạch tập trung sang kinh tế thị trường định hướng XHCN. Trước Đổi Mới, lạm phát lên đến 700%, hàng hóa khan hiếm, đời sống khó khăn. Sau Đổi Mới, Việt Nam từ nước nhập khẩu gạo trở thành nước xuất khẩu gạo lớn thứ 2-3 thế giới. GDP bình quân đầu người tăng từ ~100 USD (1986) lên hơn 4.000 USD (2023). Tỷ lệ nghèo giảm từ 58% xuống dưới 5%. Bước ngoặt vĩ đại nhất trong lịch sử kinh tế Việt Nam hiện đại.", descriptionEn: "The 6th Party Congress launched Doi Moi – shifting from centralized planning to a socialist-oriented market economy. Before Doi Moi, inflation reached 700%, goods were scarce, and living standards were dire. After Doi Moi, Vietnam went from rice importer to 2nd-3rd largest rice exporter globally. GDP per capita rose from ~$100 (1986) to over $4,000 (2023). Poverty rate dropped from 58% to under 5%. The greatest turning point in modern Vietnamese economic history." },
  { year: "1995", title: "Gia nhập ASEAN", titleEn: "Joined ASEAN", description: "Việt Nam chính thức gia nhập ASEAN ngày 28/7/1995 và bình thường hóa quan hệ ngoại giao với Hoa Kỳ ngày 11/7/1995. Hai sự kiện lịch sử diễn ra cùng tháng đánh dấu sự hội nhập toàn diện của Việt Nam vào cộng đồng quốc tế sau nhiều thập kỷ chiến tranh và cô lập. Từ đây, Việt Nam theo đuổi chính sách 'đa phương hóa, đa dạng hóa quan hệ quốc tế', thiết lập quan hệ ngoại giao với hơn 190 quốc gia và vùng lãnh thổ, trở thành đối tác tin cậy trong khu vực.", descriptionEn: "Vietnam officially joined ASEAN on July 28, 1995, and normalized diplomatic relations with the United States on July 11, 1995. These two historic events in the same month marked Vietnam's comprehensive integration into the international community after decades of war and isolation. From then, Vietnam pursued 'multilateralization and diversification of international relations', establishing diplomacy with over 190 countries and becoming a trusted regional partner." },
  { year: "2007", title: "Gia nhập WTO", titleEn: "Joined WTO", description: "Việt Nam trở thành thành viên thứ 150 của Tổ chức Thương mại Thế giới (WTO) ngày 11/1/2007, sau 11 năm đàm phán. Mở ra cơ hội xuất khẩu, đầu tư nước ngoài (FDI đạt kỷ lục 71 tỷ USD năm 2008) và chuyển giao công nghệ. GDP tăng trưởng trung bình 6-7%/năm. Việt Nam trở thành 'công xưởng mới của châu Á' với Samsung, Intel, LG đặt nhà máy lớn. Kim ngạch xuất nhập khẩu tăng từ 84 tỷ USD (2006) lên hơn 730 tỷ USD (2023), khẳng định vị thế kinh tế mở.", descriptionEn: "Vietnam became the 150th member of the World Trade Organization on January 11, 2007, after 11 years of negotiation. This opened export opportunities, foreign investment (FDI hit a record $71 billion in 2008), and technology transfer. GDP grew at 6-7% annually. Vietnam became 'Asia's new factory' with Samsung, Intel, LG establishing major plants. Trade volume grew from $84 billion (2006) to over $730 billion (2023), affirming its open economy status." },
  { year: "2020", title: "Chủ tịch ASEAN lần 2", titleEn: "ASEAN Chair 2020", description: "Việt Nam đảm nhận vai trò Chủ tịch ASEAN lần thứ 2 với chủ đề 'Gắn kết và Chủ động thích ứng' và Ủy viên không thường trực Hội đồng Bảo an LHQ (2020-2021) với số phiếu kỷ lục 192/193. Trong bối cảnh đại dịch COVID-19, Việt Nam được quốc tế ca ngợi về khả năng ứng phó hiệu quả với chi phí thấp. Nền kinh tế vẫn tăng trưởng dương 2.9% khi hầu hết thế giới suy thoái. Khẳng định vị thế ngoại giao đa phương và năng lực lãnh đạo khu vực ngày càng quan trọng trên trường quốc tế.", descriptionEn: "Vietnam assumed the ASEAN Chairmanship for the second time with the theme 'Cohesive and Responsive' and served as a non-permanent member of the UN Security Council (2020-2021) with a record 192/193 votes. Amid COVID-19, Vietnam was internationally praised for its effective, low-cost pandemic response. The economy still grew 2.9% while most of the world was in recession. This affirmed its growing multilateral diplomatic stature and regional leadership capability on the world stage." },
];

